mapper.select:
SELECT
FROM lease_order o LEFT JOIN store s ON s.id = o.store_id AND s.deleted = 0 LEFT JOIN store rs ON rs.id = o.return_store_id AND rs.deleted = 0 LEFT JOIN sys_user u ON u.id = o.user_id AND u.deleted = 0 WHERE o.deleted = 0
AND o.status = #{q.status}
AND o.store_id = #{q.storeId}
AND o.start_date >= #{q.startFrom}
AND o.start_date <= #{q.startTo}
AND ( o.order_no LIKE CONCAT('%', #{q.keyword}, '%') OR u.username LIKE CONCAT('%', #{q.keyword}, '%') OR u.real_name LIKE CONCAT('%', #{q.keyword}, '%') OR u.phone LIKE CONCAT('%', #{q.keyword}, '%') )
ORDER BY o.create_time DESC, o.id DESC
